import math

def sigmoid(z):
    return 1 / (1 + math.exp(-z))

def chain_factor(slopes):
    p = 1
    for s in slopes:
        p *= s
    return p

def sigmoid_chain(zs):
    return chain_factor([sigmoid(z) * (1 - sigmoid(z)) for z in zs])

