problems.solution:
import numpy as np

def he_init(n_in, n_out, rng):
    return rng.normal(size=(n_out, n_in)) * np.sqrt(2 / n_in)

def signal_sizes(std_fn, depth, width, rng):
    X = rng.normal(size=(width, 64))
    sizes = []
    for _ in range(depth):
        W = rng.normal(size=(width, width)) * std_fn(width)
        X = np.maximum(0, W @ X)
        sizes.append(X.std())
    return sizes
